kit.score(function (S, T) {
  const BPM = 84, B = 60 / BPM;
  S.tempo(BPM, { t0: 0 });
  S.program('pad', 'pad', { rev: 0.7 });
  S.program('keys', 'ep', { rev: 0.4 });
  S.program('mallet', 'vibes', { rev: 0.5, pan: 0.2 });
  S.program('bass', 'bass');
  S.chord('pad', ['D3', 'A3', 'E4'], { t: 0, dur: 5, vel: 40 });
  S.chord('pad', ['B2', 'F#3', 'D4'], { t: 5, dur: 5, vel: 38 });
  S.chord('keys', ['D3', 'F#3', 'A3', 'E4'], { beat: 0, beats: 4, vel: 46 });
  S.chord('keys', ['G2', 'D3', 'B3', 'F#4'], { beat: 4, beats: 4, vel: 44 });
  S.chord('keys', ['B2', 'F#3', 'A3', 'D4'], { beat: 8, beats: 4, vel: 44 });
  S.chord('keys', ['A2', 'E3', 'A3', 'C#4'], { beat: 12, beats: 2, vel: 42 });
  S.note('bass', 'D2', { beat: 0, beats: 3, vel: 64 });
  S.note('bass', 'G1', { beat: 4, beats: 3, vel: 60 });
  S.note('bass', 'B1', { beat: 8, beats: 3, vel: 60 });
  S.note('bass', 'A1', { beat: 12, beats: 2, vel: 58 });
  S.pattern('mallet', 'x..x..x.x...x.x.', { from: 0, step: 0.5, repeat: 1, pitch: ['A5', 'F#5', 'E5', 'D5', 'F#5', 'A5'], vel: 40 });
  S.pattern('mallet', 'x..x..x.....x...', { from: 8, step: 0.5, repeat: 1, pitch: ['B5', 'A5', 'F#5', 'D6'], vel: 38 });
  S.drums({ shaker: 'oxoxoxox' }, { from: 4, repeat: 2, vel: 40 });
  S.fx('sparkle', 0.05, { vel: 36 });
  S.fx('sparkle', 5.0, { vel: 30 });
  S.master({ gain: -7, fadeOut: 1.5 });
});
